"""Conversions between the application models and the "categories" table: what the service takes and returns."""

from __future__ import annotations

from app.application_models import CategoryDto
from app.entities.category import Category


def category_dto_to_category(model: CategoryDto) -> Category:
    """A CategoryDto as the categories table takes it."""
    return Category(
        name=model.name,
    )


def category_to_category_dto(row: Category) -> CategoryDto:
    """A row of the categories table as a CategoryDto."""
    return CategoryDto(
        id=row.id,
        name=row.name,
    )

