from __future__ import annotations

from app.application_models import Customer as CustomerModel
from app.entities.customer import Customer


def customer_model_to_customer(model: CustomerModel) -> Customer:
    """A Customer as the customers table takes it."""
    return Customer(
        email=model.email,
        password_hash=model.password_hash,
    )


def customer_to_customer_model(row: Customer) -> CustomerModel:
    """A row of the customers table as a Customer."""
    return CustomerModel(
        id=row.id,
        email=row.email,
        password_hash=row.password_hash,
    )

